(3853155, 544999, 16402, '<td valign="top">For me the "high-key" look of this really doesn''t work (too much detail missing), but I understand it may have been the only way to make photo work.</td>', 'For me the "high-key" look of this really doesn''t work (too much detail missing), but I understand it may have been the only way to make photo work.', '2007-07-01 09:48:50.000000', NULL, 1),
(3853163, 544857, 16402, '<td valign="top">Clever, cute and well executed.</td>', 'Clever, cute and well executed.', '2007-07-01 09:57:10.000000', NULL, 1),
(3853168, 542024, 16402, '<td valign="top">Very cool and well done. The "chip" pattern fits into the dragon flies wings perfectly and colors work great together. 7 for now and may get a bump before voting ends.</td>', 'Very cool and well done. The "chip" pattern fits into the dragon flies wings perfectly and colors work great together. 7 for now and may get a bump before voting ends.', '2007-07-01 09:59:32.000000', NULL, 1),
