(3853220, 543104, 23098, '<td valign="top">Very sci-fi, nice work.</td>', 'Very sci-fi, nice work.', '2007-07-01 10:23:03.000000', NULL, 1),
(3853227, 544816, 23098, '<td valign="top">Chilling and other worldy. Nice work.</td>', 'Chilling and other worldy. Nice work.', '2007-07-01 10:24:41.000000', NULL, 1),
